import { cn } from '@/lib/utils'

/**
 * The NexoraGuru mark — "Diya Shirorekha": the initials N and G hang from one
 * headline bar, the way Devanagari letters hang from their shirorekha, and a
 * diya flame (the guru's light of knowledge) sits on that line between them.
 *
 * Like the old mark it is a self-contained tile (deep indigo + gold foil), so
 * it reads the same on every palette, light or dark; only the wordmark follows
 * the theme. Artwork lives in public/brand/ and is generated by
 * scripts/brand/build-brand.mjs — at 32 px and below we use the hinted flat
 * variant, above that the 3D master.
 */
export function LogoMark({ size = 32, className }: { size?: number; className?: string }) {
  const src = size <= 32 ? '/brand/ngmark-flat.svg' : '/brand/ngmark.svg'
  return (
    <img
      src={src}
      width={size}
      height={size}
      alt=""
      aria-hidden="true"
      draggable={false}
      className={cn('shrink-0 select-none', className)}
    />
  )
}

/** "NexoraGuru" — the name in the theme's ink, "Guru" in gold foil (deeper gold on light themes). */
export function Wordmark({ className }: { className?: string }) {
  return (
    <span
      className={cn(
        'font-[family-name:var(--font-brand)] text-[16px] font-semibold tracking-[-0.012em] whitespace-nowrap text-text-primary',
        className,
      )}
    >
      Nexora
      <span className="bg-gradient-to-b from-[#c4811c] via-[#a8661a] to-[#7f4a0f] bg-clip-text text-transparent dark:from-[#fde9ad] dark:via-[#efbd52] dark:to-[#c98a26]">
        Guru
      </span>
    </span>
  )
}
